    # Form feed, vertical tab, NBSP, NEL, U+2028 and friends are whitespace,
    # so a category holding one is not "one word" (same rule as `add`).
    for ch in ["\x0c", "\x0b", "\xa0", "\x85", " ", " ", "　", "\x1c"]:
        for category in ("a" + ch, ch + "a", "a" + ch + "b", ch):
